package com.intelligentrecruitment.notifications.application;
import com.intelligentrecruitment.shared.error.ApiException;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;import static com.intelligentrecruitment.shared.database.SqlTimes.timestamp;
@Service public class NotificationService{private final JdbcTemplate jdbc;public NotificationService(JdbcTemplate jdbc){this.jdbc=jdbc;}public Page list(UUID userId,int limit){int size=Math.min(100,Math.max(1,limit));List<Item> items=jdbc.query("SELECT id,type,title,content,link,read_at,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT ?",(r,n)->new Item(r.getObject("id",UUID.class),r.getString("type"),r.getString("title"),r.getString("content"),r.getString("link"),r.getTimestamp("read_at")!=null?r.getTimestamp("read_at").toInstant():null,r.getTimestamp("created_at").toInstant()),userId,size);Integer unread=jdbc.queryForObject("SELECT count(*) FROM notifications WHERE user_id=? AND read_at IS NULL",Integer.class,userId);return new Page(items,unread==null?0:unread);} @Transactional public void markRead(UUID userId,UUID id){int n=jdbc.update("UPDATE notifications SET read_at=? WHERE id=? AND user_id=?",timestamp(Instant.now()),id,userId);if(n==0)throw new ApiException("NOTIFICATION_NOT_FOUND","通知不存在",HttpStatus.NOT_FOUND);}@Transactional public void markAllRead(UUID userId){jdbc.update("UPDATE notifications SET read_at=? WHERE user_id=? AND read_at IS NULL",timestamp(Instant.now()),userId);}public void create(UUID userId,String type,String title,String content,String link){jdbc.update("INSERT INTO notifications(id,user_id,type,title,content,link,created_at) VALUES(?,?,?,?,?,?,?)",UUID.randomUUID(),userId,type,title,content,link,timestamp(Instant.now()));}public record Item(UUID id,String type,String title,String content,String link,Instant readAt,Instant createdAt){}public record Page(List<Item> items,int unreadCount){}}
